sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var roomId = request.pathParams.room_id;

    // Only ever serve the photo attached to this room's own "Room image" field
    var room = new GlideRecord('x_2206701_hotel_0_rooms');
    if (!roomId || !room.get(roomId)) {
        response.setStatus(404);
        return;
    }

    var attachId = room.getValue('room_image');
    if (!attachId) {
        response.setStatus(404);
        return;
    }

    var att = new GlideRecord('sys_attachment');
    if (!att.get(attachId)) {
        response.setStatus(404);
        return;
    }

    // Images only
    var type = att.getValue('content_type') || '';
    if (type.indexOf('image/') !== 0) {
        response.setStatus(404);
        return;
    }

    var stream = new GlideSysAttachment().getContentStream(attachId);
    response.setStatus(200);
    response.setContentType(type);
    response.setHeader('Cache-Control', 'public, max-age=300');
    response.getStreamWriter().writeStream(stream);
})(request, response);
